// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
    }

    function testFuzz_property(uint256 initialDeposit, uint256 collectAmt) public {
        vm.assume(initialDeposit <= VALUE_CAP);
        // Admissible domain: keep amounts small enough to avoid overflow in the
        // mutant's balance addition, and require a non-zero collectable amount.
        initialDeposit = bound(initialDeposit, 1, type(uint128).max);
        collectAmt = bound(collectAmt, 1, type(uint128).max);
        vm.assume(initialDeposit <= type(uint256).max - collectAmt);

        address actor = address(0xA11CE);

        // Set up the required LogFile so Deposit/Collect external calls succeed.
        c.SetLogFile(address(log_));
        c.SetMinSum(0);
        c.Initialized();

        // Fund and deposit for the actor.
        vm.deal(actor, initialDeposit);
        vm.prank(actor);
        c.Deposit{value: initialDeposit}();

        uint256 balBefore = c.balances(actor);
        vm.assume(balBefore >= collectAmt);

        // Ensure the actor can receive the ETH refund from Collect.
        vm.deal(actor, 0);

        vm.prank(actor);
        bool ok;
        try c.Collect{value: 0}(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = c.balances(actor);

        // General rule: on success, the actor's recorded balance must decrease by exactly _am.
        // P: balBefore - balAfter == _am. M: balAfter == balBefore + _am, so the rule fails.
        assertTrue(!ok || balAfter == balBefore - collectAmt);
    }
}
